#include <cstdio>
#include <vector>

int main() {
    int n;
    scanf("%d", &n);
    std::vector<long long> a(n);
    for (int i = 0; i < n; ++i) scanf("%lld", &a[i]);

    int k = 0;
    for (int fast = 0; fast < n; ++fast) {
        if (k == 0 || a[fast] != a[k - 1]) {
            a[k++] = a[fast];
        }
    }

    printf("%d\n", k);
    for (int i = 0; i < k; ++i) {
        if (i) printf(" ");
        printf("%lld", a[i]);
    }
    printf("\n");
    return 0;
}
